from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_val: str = Form(...), file_val: bytes = File(...)):
    return {"form_val": form_val, "file_val": file_val}

client = TestClient(app)

def test_file_after_form():
    # When File is declared after Form, it should still work if it's bytes
    # The bug causes a 422 if the logic incorrectly assumes it's not a File field
    # because the FIRST field was a Form field.
    response = client.post(
        "/test",
        data={"form_val": "hello", "file_val": b"world"},
    )
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "world"} # bytes are converted to string in json response usually or handled by fastapi

def test_file_first():
    @app.post("/test_first")
    async def test_endpoint_first(file_val: bytes = File(...), form_val: str = Form(...)):
        return {"form_val": form_val, "file_val": file_val}

    response = client.post(
        "/test_first",
        data={"form_val": "hello", "file_val": b"world"},
    )
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "world"}
